/bin/bash -lc "timeout 8s python - <<'PY'
import re,time
for pat in [rb'(<head(?:>|\\s.*?>))', rb'(<head(?:>|\\s["'^>]*>))'"']:
 for suffix in [b'', b'>']:
  for n in [1000,2000,4000]:
   data=b'<head\\t'*n+suffix
   t=time.process_time(); m=re.search(pat,data); dt=time.process_time()-t
   print(pat, bool(suffix), n, round(dt,4), bool(m), flush=True)
PY"

