/bin/bash -lc "python - <<'PY'
import re,time
for func in ['search','sub']:
 for n in [1000,2000,4000]:
  d=b'-><"'!--'"\\x00'*n+b'->\\n<"'!---->'"'
  p=re.compile(rb'<"'!--.*?-->'"')
  t=time.process_time()
  if func=='search': r=p.search(d)
  else: r=p.sub(b'',d)
  print(func,n,round(time.process_time()-t,4), r if func=='search' else len(r), flush=True)
PY"

