/bin/bash -lc "python - <<'PY'
import re,time
cases={
 'current': lambda n: b'-><"'!--'"\\x00'*n + b'->\\n<"'!---->'"',
 'no_suffix': lambda n: b'-><"'!--'"\\x00'*n,
 'plain': lambda n: b'<"'!--'"'*n,
 'recheck_maybe': lambda n: b'<"'!--'"\\x00'*n,
}
for flags,name in [(re.DOTALL,'DOTALL'),(0,'noflags')]:
 print(name)
 for cname,f in cases.items():
  for n in [1000,2000,4000]:
   d=f(n)
   t=time.process_time(); re.sub(rb'<"'!--.*?-->'"',b'',d,flags=flags); dt=time.process_time()-t
   print(' ',cname,n,round(dt,4))
PY"

